"""Browser and real-speech tests (issue #25). Opt-in so `bash scripts/check.sh` stays fast and keyless.

PAWSE_E2E=1 collects the Playwright tests (test_browser_*.py); they need `pip install -r
requirements-e2e.txt` and `python -m playwright install chromium`. The speech-metric tests always run;
the real-recording tests skip themselves unless PAWSE_LIVE_SPEECH=1 (see README.md).
"""
import importlib.util
import os
import socket
import subprocess
import sys
import time
from pathlib import Path

import httpx
import pytest

ROOT = Path(__file__).resolve().parents[2]
KEYS = ("GEMINI_API_KEY", "GRADIUM_API_KEY", "GRADIUM_VOICE_ID_DE", "GRADIUM_STANDARD_VOICE_ID_DE",
        "GOOGLE_PLACES_API_KEY", "MAPIFY_BASE_URL")

if os.getenv("PAWSE_E2E") != "1" or importlib.util.find_spec("playwright") is None:
    collect_ignore_glob = ["test_browser_*.py"]


def serve(env):
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        port = s.getsockname()[1]
    proc = subprocess.Popen([sys.executable, "-m", "uvicorn", "pawse.app:app", "--host", "127.0.0.1", "--port", str(port)],
                            cwd=ROOT, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    url = f"http://127.0.0.1:{port}"
    for _ in range(100):
        try:
            if httpx.get(f"{url}/api/v1/health", timeout=1).status_code == 200:
                return proc, url
        except httpx.HTTPError:
            pass
        if proc.poll() is not None:
            raise RuntimeError(f"uvicorn exited: {proc.stderr.read().decode()[-2000:]}")
        time.sleep(0.1)
    proc.terminate()
    raise RuntimeError("uvicorn did not become healthy within 10 s")


@pytest.fixture(scope="session")
def app_server():
    """The real app with every provider key blanked: browser tests mock the network at the page."""
    proc, url = serve(os.environ | {key: "" for key in KEYS})
    yield url
    proc.terminate()
    proc.wait(10)


@pytest.fixture(scope="session")
def speech_wav(tmp_path_factory):
    from audio_fixtures import speechlike
    path = tmp_path_factory.mktemp("audio") / "speechlike.wav"
    path.write_bytes(speechlike(seconds=6))
    return path


def fake_mic_args(wav_path, loop=True):
    """Chromium's fake capture device plays this WAV as the microphone (no real hardware)."""
    return ["--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream",
            f"--use-file-for-fake-audio-capture={wav_path}{'' if loop else '%noloop'}",
            "--autoplay-policy=no-user-gesture-required"]


@pytest.fixture(scope="session")
def browser_type_launch_args(browser_type_launch_args, speech_wav):
    return {**browser_type_launch_args, "args": fake_mic_args(speech_wav)}


@pytest.fixture(scope="session")
def browser_context_args(browser_context_args, app_server):
    return {**browser_context_args, "base_url": app_server, "permissions": ["microphone"],
            "viewport": {"width": 1440, "height": 900}}


@pytest.fixture(autouse=True)
def no_console_errors(request):
    """Every browser test also fails on a console error or an uncaught page exception."""
    if not request.node.path.name.startswith("test_browser_"):
        yield
        return
    page = request.getfixturevalue("page")
    errors = []
    page.on("console", lambda m: m.type == "error" and errors.append(m.text))
    page.on("pageerror", lambda e: errors.append(str(e)))
    yield
    assert not errors, f"console errors: {errors}"


@pytest.fixture
def transcriptions(page):
    """Captures POST /voice/transcriptions bodies and answers with a canned transcript."""
    seen = []

    def handle(route):
