  for (let i=0;i<samples.length;i++) view.setInt16(i*2, Math.round(Math.max(-1,Math.min(1,samples[i]))*32767), true);
  let s=''; for (let i=0;i<bytes.length;i+=8192) s+=String.fromCharCode(...bytes.subarray(i,i+8192));
  return btoa(s);
}
