@pytest.mark.parametrize("language", ["en"])
def test_probe(browser_type, live_app, language):
    entry = FIRST[language]; log = []
    b = browser_type.launch(args=["--autoplay-policy=no-user-gesture-required"])
    page = b.new_page(base_url=live_app)
