    page.add_init_script(RECORDING_AS_MIC)
    def handler(ws):
        server = ws.connect_to_server()
        def from_server(m):
            try:
                d = json.loads(m if isinstance(m, str) else m.decode()); sc = d.get("serverContent", {})
                for k in ("inputTranscription", "outputTranscription"):
                    if k in sc: log.append((k[:2], sc[k].get("text")))
                for k in ("interrupted", "turnComplete"):
                    if sc.get(k): log.append((k, ""))
                if "toolCall" in d: log.append(("tool", d["toolCall"]["functionCalls"][0]["name"]))
            except Exception: pass
